import type { PointKey } from "../types";

/**
 * Textes dédiés par planète × 12 maisons, sur le même principe que
 * planet-in-sign.ts : structure en trois temps (ce que la maison prend
 * comme couleur avec cette planète, où ça coince, ce qu'il y a à
 * apprendre). Couverture volontairement partielle pour l'instant — les
 * combinaisons non couvertes retombent sur le gabarit générique de
 * describePlanetInHouse dans compose.ts.
 */
export const PLANET_IN_HOUSE: Partial<Record<PointKey, Record<number, string>>> = {
  sun: {
    1: "Le Soleil en maison I place l'identité en pleine lumière dès le premier regard : la présence est immédiatement lisible, l'énergie vitale se voit dans le corps, la voix, la façon d'entrer quelque part, on sait vite à qui on a affaire. Ce qui coûte le plus se joue dans le besoin d'être vu : cette identité si frontale peut glisser vers un centrage sur soi permanent, une difficulté à céder la scène, ou une confiance qui masque en réalité une dépendance au regard des autres pour se sentir exister. Ce qu'il y a à intégrer est que la vitalité n'a pas besoin d'un public pour être réelle.",
    2: "Le Soleil en maison II ancre l'identité dans le tangible : ce qu'on possède, ce qu'on gagne, ce qu'on construit de ses mains devient une extension directe de qui l'on est, avec souvent un vrai talent pour faire fructifier des ressources. Le point sensible se loge dans la confusion des valeurs : cette identité si liée au matériel peut faire dépendre l'estime de soi du solde du compte en banque, ou pousser à prouver sa valeur par ce qu'on accumule plutôt que par ce qu'on est. Ce qu'il y a à travailler est que la valeur personnelle précède ce qu'elle produit, elle ne s'y résume pas.",
    3: "Le Soleil en maison III exprime l'identité par la parole, la curiosité et le lien immédiat, fratrie, voisinage, échanges du quotidien : on se sent le plus soi-même en train d'apprendre, de discuter, de relier des idées entre elles. Le revers se joue dans la dispersion : cette identité si mobile peut s'éparpiller sur trop de sujets à la fois, chercher la validation dans chaque échange plutôt que dans une pensée réellement approfondie. Grandir ici consiste à apprendre que certaines idées méritent d'être creusées jusqu'au bout plutôt que simplement évoquées.",
    4: "Le Soleil en maison IV enracine l'identité dans le foyer et les origines : on se sent pleinement soi-même dans un cadre familier, avec un besoin réel de sécurité affective pour oser se montrer ailleurs. La difficulté se niche dans la fusion : cette identité si liée aux racines peut se confondre avec un rôle familial hérité, porter l'histoire des siens au point de ne plus savoir ce qui, dans cette identité, appartient vraiment en propre. Le terrain de maturation est d'apprendre que le foyer est une base, pas la totalité de qui l'on est.",
    5: "Le Soleil en maison V s'exprime pleinement dans la créativité, le jeu, l'amour et tout ce qui donne envie d'être admiré : on se sent le plus vivant en créant, en aimant sans retenue, en étant vu et applaudi pour ce qu'on fait. Ce qui coince se joue dans la dépendance à l'admiration : cette identité si tournée vers la scène peut avoir besoin d'applaudissements constants pour se sentir réelle, jusqu'à dramatiser ce qui ne l'exigeait pas. Ce qu'il y a à travailler est de continuer à créer même sans public, pour la joie du geste lui-même.",
    6: "Le Soleil en maison VI construit l'identité par l'utilité, le travail bien fait et le soin apporté au quotidien : on se sent pleinement soi-même en étant compétent, utile, capable de tenir une routine avec rigueur. Le prix à payer se loge dans la fusion entre valeur et service : cette identité si centrée sur l'utilité peut s'effondrer dès qu'on ne se sent plus indispensable, pousser vers un perfectionnisme épuisant ou une identité entièrement suspendue au travail accompli. Grandir ici, c'est apprendre que la valeur personnelle ne se mérite pas uniquement par ce qu'on produit.",
    7: "Le Soleil en maison VII se révèle pleinement dans le miroir de l'autre : c'est souvent dans la relation, l'engagement ou le face-à-face qu'on se sent le plus complètement soi-même, comme si l'identité avait besoin d'un vis-à-vis pour se préciser. La tension se noue dans la dépendance : cette identité si liée au partenariat peut se dissoudre hors de la relation, chercher chez l'autre ce qui devrait se construire en soi, ou définir sa valeur uniquement par le regard d'un partenaire. Le terrain de maturation est de bâtir une identité qui tient debout seule, avant même de se refléter dans l'autre.",
    8: "Le Soleil en maison VIII se forge dans l'intensité : crises, transformations, intimité profonde et tout ce qui touche à ce qui reste habituellement caché deviennent le terrain où l'identité se sent la plus vraie. Ce qui grince se joue dans le besoin d'intensité : cette identité si liée aux extrêmes peut se sentir vide dans le calme, rechercher la crise pour se sentir vivante, ou avoir du mal à se montrer vulnérable malgré une profondeur réelle. Ce qu'il y a à intégrer est qu'exister pleinement ne demande pas toujours une transformation ou une épreuve pour se justifier.",
    9: "Le Soleil en maison IX s'exprime à travers la quête de sens, les croyances, les études supérieures et tout horizon qui dépasse le quotidien : on se sent le plus soi-même en explorant, en enseignant, en élargissant sa vision du monde. Ce qui coûte le plus se joue dans la certitude : cette identité si attachée à sa propre vérité peut glisser vers le dogmatisme, ou lier l'estime de soi à l'idée d'avoir raison plutôt qu'à l'ouverture réelle. Ce que ce placement invite à comprendre est que rester soi-même n'empêche pas d'accueillir une vision différente de la sienne.",
    10: "Le Soleil en maison X trouve sa pleine expression dans le rôle public, la carrière et la reconnaissance : on se sent le plus soi-même en étant vu et valorisé pour ce qu'on accomplit, avec souvent une vraie vocation à occuper une position visible. Le point sensible se loge dans la dépendance au statut : cette identité si tournée vers la réussite publique peut s'effondrer sans reconnaissance extérieure, pousser à un épuisement au nom de l'image, ou négliger tout ce qui, en soi, ne se montre pas. La leçon à emporter est que la valeur personnelle ne dépend pas uniquement du titre qu'on porte.",
    11: "Le Soleil en maison XI s'exprime pleinement dans le collectif : groupes, amitiés, causes partagées et vision d'avenir deviennent le lieu où l'identité se sent la plus vivante, portée par un sentiment réel d'appartenance. Le revers se joue dans la dilution : cette identité si tournée vers le groupe peut se fondre dans une cause ou une bande d'amis au point de perdre ce qui la rend singulière. Le terrain de maturation est d'apprendre à rester pleinement soi tout en appartenant vraiment à un collectif.",
    12: "Le Soleil en maison XII se vit en retrait : l'identité se sent le plus vraie dans l'invisible, le spirituel, le service discret ou l'introspection, loin des projecteurs que d'autres placements recherchent naturellement. La difficulté se niche dans l'effacement : cette identité si peu portée vers la visibilité peut avoir du mal à revendiquer sa place, se sentir transparente, ou se sacrifier au point de ne plus savoir ce qu'elle veut vraiment pour elle-même. Ce qui aide à mûrir ici est de saisir que revendiquer une identité ne demande pas d'être constamment vue, mais demande d'exister, au moins, pour soi.",
  },
  moon: {
    1: "La Lune en maison I porte les émotions à la surface : l'humeur se lit immédiatement sur le visage ou dans l'attitude, la sensibilité colore la première impression avant même qu'un mot soit prononcé. Ce qui coince se joue dans la lisibilité : cette identité si perméable au ressenti peut faire dépendre l'image de soi des variations d'humeur du moment, au point que les autres croient connaître l'état intérieur avant qu'il ait été partagé. Le vrai travail consiste à apprendre que le ressenti peut informer la présence sans la dicter entièrement.",
    2: "La Lune en maison II lie la sécurité émotionnelle au tangible : avoir des réserves, un cadre matériel stable, apaise profondément, parfois jusqu'à chercher du réconfort dans la nourriture, les achats ou l'accumulation. Le prix à payer se loge dans la disproportion : cette sécurité si liée au matériel peut générer une anxiété financière hors de proportion avec la réalité, ou faire fluctuer l'estime de soi au rythme du compte en banque. Ce qu'il y a à intégrer est que la sécurité la plus solide se construit d'abord à l'intérieur, avant de se loger dans ce qu'on possède.",
    3: "La Lune en maison III a besoin de parler pour se sentir apaisée : les échanges avec la fratrie, le voisinage, les conversations du quotidien nourrissent directement l'équilibre émotionnel. La tension se noue dans l'instabilité du dialogue : cette sensibilité si liée à la parole peut basculer d'humeur au fil d'une simple conversation, ou chercher une réassurance constante à travers les mots plutôt qu'à travers un ressenti stabilisé de l'intérieur. Ce qu'il y a à travailler est que tout ce qui se ressent n'a pas besoin d'être dit à voix haute pour être vrai.",
    4: "La Lune est chez elle en maison IV : le besoin de racines, de foyer et de sécurité affective y est le plus fondamental, avec souvent une mémoire sensorielle intense de l'enfance qui continue de colorer le présent. Ce qui grince se joue dans l'attachement : cette sécurité si liée au passé familial peut rendre difficile de s'en détacher émotionnellement, ou faire dépendre l'humeur entière des changements dans le cadre domestique. Ce qu'il y a à travailler est de construire un foyer intérieur, pas seulement un lieu, pour que la sécurité ne dépende plus uniquement des murs.",
    5: "La Lune en maison V trouve son apaisement dans la création, le jeu et l'amour vécu sans retenue : le besoin d'être touché émotionnellement par ce qu'on fait ou par qui on aime est réel et profond. Ce qui coûte le plus se joue dans la dépendance affective : ce besoin d'être adoré peut chercher une validation romantique ou créative constante pour se sentir bien, jusqu'à dramatiser une relation ou un projet pour continuer à ressentir cette intensité. Le terrain de maturation est d'apprendre à s'apaiser soi-même, sans attendre que l'admiration vienne de l'extérieur.",
    6: "La Lune en maison VI lie le bien-être émotionnel à la routine et à l'utilité : un quotidien bien réglé, un corps pris en charge, un sentiment d'être utile apaisent profondément, et à l'inverse, l'anxiété s'y loge facilement dans le corps. Le point sensible se loge dans l'hypervigilance : cette sensibilité si attachée aux détails du quotidien peut basculer vers une inquiétude excessive au moindre grain de sable dans la routine, ou faire dépendre l'équilibre intérieur entier du stress professionnel. Ce qu'il y a à intégrer est de prendre soin sans perdre son propre équilibre en chemin.",
    7: "La Lune en maison VII se régule au contact de l'autre : l'humeur du partenaire ou de la relation affecte profondément l'équilibre intérieur, avec une vraie capacité à ressentir ce que l'autre traverse, presque par fusion. Le revers se joue dans la porosité : cette sensibilité si liée au lien peut faire perdre son propre centre émotionnel dans une relation, absorber les humeurs de l'autre comme si elles étaient les siennes. Le terrain de maturation est d'apprendre la proximité sans perdre son ancrage émotionnel propre.",
    8: "La Lune en maison VIII ressent tout avec une profondeur rare : l'intimité, la crise, la transformation attirent naturellement, avec une intuition souvent aiguë pour ce qui reste caché chez les autres. La difficulté se niche dans l'intensité difficile à partager : ce ressenti si profond peut se transformer en méfiance, en jalousie ou en humeurs extrêmes vécues en privé, avec une vraie difficulté à laisser voir cette vulnérabilité. Le terrain de maturation est d'apprendre que la profondeur n'a pas besoin d'être dramatique pour être réelle.",
    9: "La Lune en maison IX se rassure dans le sens, la croyance et l'ailleurs : voyager, apprendre, croire en quelque chose de plus grand que le quotidien apaise véritablement, comme un besoin réel d'horizon pour se sentir bien. Ce qui coince se joue dans la fuite : ce besoin de sens peut servir à éviter un ressenti trop inconfortable en le noyant dans l'abstraction, le voyage ou la philosophie plutôt que de le traverser directement. Grandir ici, c'est apprendre que le sens aide à digérer une émotion, il ne remplace pas le fait de la ressentir.",
    10: "La Lune en maison X expose la vie émotionnelle sur la scène publique : l'humeur se lit parfois jusque dans la vie professionnelle, avec un besoin réel d'être reconnu et « porté » par sa réussite ou son rôle social. Le prix à payer se loge dans le sacrifice du privé : ce besoin de reconnaissance peut faire dépendre l'équilibre intérieur entier de l'image professionnelle, au point de négliger des besoins émotionnels que personne ne voit. Ce que ce placement invite à comprendre est que les besoins affectifs méritent d'être pris en compte même loin des regards.",
    11: "La Lune en maison XI se sent chez elle dans le collectif : amitiés, groupes et causes partagées nourrissent profondément l'équilibre émotionnel, avec un vrai besoin d'appartenance pour se sentir bien. La tension se noue dans la loyauté au groupe : cette sensibilité si liée à l'appartenance peut rendre difficile d'exprimer un désaccord réel de peur de perdre sa place dans le cercle. Ce qu'il y a à intégrer est qu'une appartenance vraiment sûre supporte le désaccord sans se briser.",
    12: "La Lune en maison XII vit une vie émotionnelle largement invisible : une sensibilité intuitive, presque psychique, souvent tournée vers le retrait, le rêve ou le sacrifice discret plutôt que vers l'expression directe. Ce qui grince se joue dans l'évitement : ce ressenti si privé peut se manifester indirectement (par le corps, les rêves, l'envie de fuir) plutôt que d'être nommé clairement. Le terrain de maturation est d'apprendre à mettre des mots sur ce qui se ressent, plutôt que de seulement le ressentir en silence.",
  },
  mercury: {
    1: "Mercure en maison I place l'esprit et la parole au premier plan de l'image donnée : la réflexion se voit, la répartie est rapide, on pense souvent à voix haute avant même d'avoir fini de formuler l'idée. Ce qui coûte le plus se joue dans la visibilité de l'agitation mentale : cette vivacité si frontale peut se lire comme de la nervosité, pousser à parler avant d'avoir vraiment senti, ou trahir une pensée qui tourne sans jamais se poser. La leçon à emporter est que toutes les pensées n'ont pas besoin d'un débouché verbal immédiat.",
    2: "Mercure en maison II pense l'argent et les ressources de façon concrète et précise : un vrai talent pour évaluer, négocier, chiffrer ce que les choses valent réellement. Le point sensible se loge dans la réduction : cet esprit si tourné vers le calculable peut ramener toute valeur à ce qui se compte, ressasser mentalement les questions d'argent, ou parler prix avant de ressentir ce qu'une chose représente vraiment. Ce qu'il y a à intégrer est qu'une valeur n'a pas toujours besoin d'être quantifiable pour être réelle.",
    3: "Mercure est chez lui en maison III : l'esprit y trouve son terrain naturel, curieux de tout ce qui l'entoure immédiatement (fratrie, voisinage, petits trajets, apprentissages du quotidien) avec une vraie aisance à faire des liens et à échanger. Le revers se joue dans la dispersion : cette curiosité si mobile peut sauter d'un sujet à l'autre sans jamais s'y attarder, parler plus qu'écouter, ou multiplier les échanges superficiels plutôt qu'un vrai approfondissement. Ce qui aide à mûrir ici est de saisir que certains sujets gagnent plus à être creusés qu'à être simplement traversés.",
    4: "Mercure en maison IV pense beaucoup l'histoire familiale et les racines : on analyse volontiers ce qui vient de l'enfance, du foyer, des schémas hérités, avec une vraie intelligence pour en comprendre les mécanismes. La difficulté se niche dans la mise à distance : cette analyse si présente peut servir à intellectualiser ce qui devrait d'abord se ressentir, créant une distance mentale avec une vie familiale qu'on préfère comprendre plutôt que vivre pleinement. Le vrai travail consiste à apprendre que certaines choses se sentent avant de s'expliquer.",
    5: "Mercure en maison V donne un esprit joueur, vif dans le badinage, la créativité et tout ce qui touche à la séduction : les idées viennent facilement, souvent portées par un vrai enthousiasme créatif. Ce qui coince se joue dans la dispersion créative : cette vivacité peut intellectualiser l'amour ou la création plutôt que de les vivre pleinement, multiplier les idées sans jamais en finir une seule. Ce qu'il y a à travailler est qu'achever une idée compte autant que l'avoir eue.",
    6: "Mercure en maison VI pense le travail et la routine de façon analytique et efficace : un vrai talent pour organiser le quotidien, résoudre des problèmes concrets, optimiser une méthode. Le prix à payer se loge dans la surveillance mentale : cette analyse si fine peut basculer vers l'hypocondrie ou l'inquiétude excessive sur le corps, épuiser l'esprit à vouloir optimiser jusqu'au moindre détail. Ce qu'il y a à intégrer est que tous les détails ne méritent pas d'être analysés.",
    7: "Mercure en maison VII engage l'esprit à travers le dialogue et le partenariat : penser à voix haute avec l'autre, valoriser une vraie connexion intellectuelle dans la relation, discuter comme une forme de proximité. La tension se noue dans la sur-analyse du lien : cette tendance peut transformer chaque désaccord en débat interminable, négocier la relation plutôt que de simplement la vivre. Le terrain de maturation est d'apprendre qu'une proximité n'a pas toujours besoin d'être discutée pour être réelle.",
    8: "Mercure en maison VIII attire l'esprit vers ce qui reste habituellement caché : psychologie, recherche, sujets tabous, avec une vraie capacité d'investigation et de perspicacité. Ce qui grince se joue dans la rumination : cette perspicacité peut se retourner en soupçon permanent sur les motivations des autres, en pensées qui tournent en boucle sur ce qu'on ne peut pas contrôler. Ce qu'il y a à travailler est que tous les mystères n'ont pas besoin d'être résolus à force d'y penser.",
    9: "Mercure en maison IX pense grand : philosophie, cultures étrangères, enseignement et grandes idées nourrissent un esprit qui a besoin d'horizon pour se sentir stimulé. Ce qui coûte le plus se joue dans la dispersion des grandes idées : cet enthousiasme peut s'éparpiller sur trop de visions à la fois sans jamais les ancrer, ou glisser vers un ton professoral qui tolère mal la contradiction. Le terrain de maturation est d'apprendre que les grandes idées gagnent en précision, pas en volume.",
    10: "Mercure en maison X met l'esprit au service de la carrière et de l'image publique : une communication stratégique, une intelligence sociale mise à profit pour la réputation professionnelle. Le point sensible se loge dans la surveillance de l'image : cette stratégie peut épuiser l'esprit à toujours calculer comment on est perçu, transformer chaque pensée en question de communication professionnelle. Grandir ici, c'est apprendre que toutes les pensées n'ont pas besoin d'un public professionnel.",
    11: "Mercure en maison XI s'épanouit dans l'échange collectif : idées qui circulent en groupe, stimulation intellectuelle par les amitiés et les causes partagées, une vraie aisance à penser à plusieurs. Le revers se joue dans la dilution : cette stimulation collective peut disperser la pensée sur trop de fils à la fois, rendre difficile de mener une idée personnelle à son terme au milieu du bruit du groupe. Le terrain de maturation est d'apprendre qu'une bonne idée a parfois besoin de solitude pour mûrir.",
    12: "Mercure en maison XII pense de façon intuitive et peu verbale : les idées viennent parfois du rêve ou de l'inconscient plutôt que de la logique directe, avec une vraie sensibilité à ce qui ne se dit pas. La difficulté se niche dans la difficulté à formuler : cette pensée si intérieure peut avoir du mal à se traduire en mots, tourner en boucle silencieusement plutôt que de se clarifier par l'échange. Ce que ce placement invite à comprendre est que certaines pensées ont besoin d'être mises en mots pour cesser de tourner en rond.",
  },
  venus: {
    1: "Vénus en maison I place le charme et le sens esthétique au cœur de l'image donnée : une présence naturellement agréable, un vrai souci d'harmonie dans la façon d'être perçu. Ce qui coince se joue dans la dépendance à l'image plaisante : cette identité si tournée vers la grâce peut éviter les conflits nécessaires pour préserver l'harmonie apparente, ou faire dépendre l'estime de soi du fait de plaire. Le terrain de maturation est d'apprendre qu'être aimé et être vrai ne sont pas toujours la même chose.",
    2: "Vénus en maison II valorise le confort, la beauté et le plaisir tangible : un vrai goût pour les belles choses, un sens esthétique qui s'exprime dans ce qu'on possède et ce dont on s'entoure. Le prix à payer se loge dans la compensation : cette recherche de confort peut faire dépendre l'estime de soi de ce qu'on possède ou de son apparence, glisser vers l'indulgence comme réconfort face à un manque plus profond. Ce qu'il y a à intégrer est qu'une valeur personnelle n'a pas besoin d'une preuve esthétique.",
    3: "Vénus en maison III donne un charme naturel dans l'échange : une parole diplomate, un vrai talent pour maintenir l'harmonie avec la fratrie et le voisinage, des conversations agréables et fluides. La tension se noue dans l'évitement : ce goût pour l'harmonie peut esquiver un conflit pourtant nécessaire dans l'échange, dire ce qui fait plaisir plutôt que ce qui est vrai. La leçon à emporter est que l'harmonie demande parfois un mot inconfortable pour rester honnête.",
    4: "Vénus en maison IV recherche un foyer beau et harmonieux : les liens familiaux se colorent d'affection et d'esthétique, avec un vrai talent pour apaiser les tensions à la maison. Ce qui grince se joue dans l'évitement du vrai : ce besoin d'harmonie peut esquiver un conflit familial nécessaire pour préserver une paix de façade, idéaliser l'entente familiale plutôt que d'en affronter les failles réelles. Le terrain de maturation est d'apprendre qu'un vrai foyer peut accueillir le désaccord sans se briser.",
    5: "Vénus s'exprime pleinement en maison V : amour, créativité et plaisir coulent naturellement, avec un charme qui brille particulièrement dans la séduction et l'expression artistique. Ce qui coûte le plus se joue dans la validation : cet amour du plaisir peut chercher l'admiration ou la validation romantique pour se sentir bien, glisser vers l'indulgence, avoir du mal avec un amour qui demande de l'effort plutôt qu'un plaisir immédiat. Ce qu'il y a à travailler est qu'un amour qui demande des efforts reste un amour véritable.",
    6: "Vénus en maison VI cherche l'harmonie jusque dans le travail et la routine : un cadre professionnel agréable, un vrai soin esthétique apporté au corps et au quotidien. Le point sensible se loge dans l'évitement professionnel : ce besoin d'harmonie peut esquiver un conflit de travail pourtant nécessaire, et l'indulgence peut fragiliser une routine ou une santé qui demanderaient plus de rigueur. Ce qui aide à mûrir ici est de saisir que l'harmonie passe parfois par affronter ce qui est inconfortable.",
    7: "Vénus est chez elle en maison VII : le partenariat est profondément valorisé, avec un vrai don pour le compromis et une aisance naturelle dans la relation à deux. Le revers se joue dans le sur-compromis : ce talent pour l'harmonie peut éviter tout conflit au prix de ses propres besoins, choisir un partenaire pour la paix qu'il apporte plutôt que pour une vraie profondeur. Le terrain de maturation est d'apprendre qu'un partenariat réel survit au désaccord, il ne l'évite pas.",
    8: "Vénus en maison VIII recherche une intimité profonde : attirée par ce qui est intense ou transformateur dans l'amour, par ce qui reste habituellement caché dans les liens et les ressources partagées. La difficulté se niche dans le contrôle : cet amour de l'intensité peut s'emmêler avec la possessivité ou la jalousie, utiliser le charme pour garder une emprise sur l'autre plutôt que pour se rapprocher vraiment. Le vrai travail consiste à apprendre que l'intimité n'a pas besoin d'intensité pour être réelle.",
    9: "Vénus en maison IX trouve la beauté dans l'ailleurs : cultures étrangères, philosophie, voyage nourrissent un sens esthétique et romantique élargi par l'exploration. Ce qui coince se joue dans l'idéalisation lointaine : cette attirance peut idéaliser un amour ou une croyance parce qu'ils viennent d'ailleurs, éviter une intimité réelle et proche au profit de l'idée d'une aventure. Ce qu'il y a à intégrer est que ce qui est beau tout près mérite la même attention que ce qui est loin.",
    10: "Vénus en maison X met le charme au service de l'image publique et de la carrière : une aisance diplomate professionnelle, un sens esthétique valorisé socialement. Le prix à payer se loge dans la conformité : ce besoin de plaire peut façonner les valeurs et les choix de carrière selon ce qui est bien vu plutôt que selon ce qui comble vraiment. Ce qu'il y a à travailler est que ce qu'on valorise en privé compte autant que ce qu'on admire en public.",
    11: "Vénus en maison XI valorise l'amitié et l'appartenance : un charme qui brille en groupe, un vrai talent diplomate au sein des causes et des collectifs partagés. La tension se noue dans l'évitement collectif : ce besoin d'harmonie peut esquiver un désaccord réel au sein du groupe par peur de perdre sa place, choisir ses amis ou ses causes pour la paix plutôt que pour l'honnêteté. Le terrain de maturation est d'apprendre qu'une appartenance vraie peut aussi accueillir le désaccord.",
    12: "Vénus en maison XII vit l'amour et la beauté en privé : une sensibilité esthétique discrète, une vraie capacité d'amour inconditionnel ou de sacrifice silencieux pour l'autre. Ce qui grince se joue dans le déséquilibre du don : cet amour si discret peut se donner à distance, avoir du mal à recevoir en retour, confondre sacrifice de soi et amour véritable. Le terrain de maturation est d'apprendre que l'amour donné mérite aussi d'être reçu.",
  },
  mars: {
    1: "Mars en maison I donne une présence affirmée et directe : on agit avant de trop réfléchir, l'énergie se voit immédiatement dans le corps et l'attitude, avec une vraie impatience à passer à l'action. Ce qui coûte le plus se joue dans la rapidité de la réaction : cette affirmation si frontale peut basculer vite vers la colère, l'impulsivité, un conflit qui se lit sur le visage avant même d'être formulé en mots. Le terrain de maturation est d'apprendre qu'une action n'a pas besoin d'être instantanée pour être efficace.",
    2: "Mars en maison II canalise l'énergie vers l'acquisition et la construction de ressources : une vraie combativité pour gagner sa vie, un désir réel de posséder ce pour quoi on se bat. Le point sensible se loge dans l'agressivité matérielle : cette combativité peut devenir dépense impulsive ou conflit ouvert autour de l'argent, confondre valeur personnelle et capacité à obtenir. Grandir ici, c'est apprendre que la patience rapporte souvent plus que la force en matière d'argent.",
    3: "Mars en maison III donne une parole vive et directe : la répartie est rapide, l'esprit compétitif dans l'échange, avec une vraie énergie dans les discussions avec la fratrie et le voisinage. Le revers se joue dans l'agressivité verbale : cette vivacité peut glisser vers l'attaque dans la conversation, l'impatience à écouter, le désaccord transformé en dispute pour un détail. Grandir ici, c'est apprendre qu'avoir raison ne demande pas de gagner chaque échange.",
    4: "Mars en maison IV enracine l'énergie dans la défense du foyer et de la famille : une vraie combativité protectrice, parfois aussi des tensions ou des conflits directement vécus en famille. La difficulté se niche dans l'irruption de la colère à la maison : cette énergie protectrice peut se déclencher même quand rien ne la justifie vraiment, défendre un territoire par réflexe plutôt que par nécessité réelle. Le terrain de maturation est d'apprendre qu'on peut défendre son foyer sans devoir constamment se battre pour lui.",
    5: "Mars en maison V poursuit l'amour et la création avec passion : une vraie audace créative, un esprit compétitif dans le jeu et la séduction, une énergie qui aime conquérir plutôt qu'attendre. Ce qui coince se joue dans l'impulsivité amoureuse ou créative : cette passion peut confondre désir de conquête et plaisir réel, se précipiter dans des choix romantiques ou créatifs sans les avoir vraiment sentis. Ce qu'il y a à travailler est qu'une passion n'a pas besoin de conquête pour être réelle.",
    6: "Mars en maison VI canalise une énergie combative dans le travail et la routine : une vraie productivité, un besoin réel de bouger et d'agir au quotidien, un esprit compétitif dans les tâches accomplies. Le prix à payer se loge dans la tension retenue : cette énergie peut virer au surmenage, à l'irritabilité dès que la routine est perturbée, à une tension physique née de la frustration accumulée. Ce que ce placement invite à comprendre est que le repos est lui aussi productif.",
    7: "Mars en maison VII fait émerger l'affirmation de soi à travers le partenariat : une vraie énergie dans la relation, une attirance pour des partenaires dynamiques ou stimulants, un désir réel de se mesurer à l'autre. La tension se noue dans le rapport de force : cette énergie peut transformer la relation en lutte de pouvoir, projeter sur le partenaire une colère qui vient d'ailleurs, chercher à gagner plutôt qu'à collaborer. Le terrain de maturation est d'apprendre qu'un partenariat peut accueillir l'affirmation de soi sans devenir un combat.",
    8: "Mars en maison VIII affronte la crise, la transformation et l'intimité profonde avec un vrai courage : une capacité réelle à regarder en face ce qui reste habituellement évité, une énergie puissante dans les enjeux partagés (argent, intimité, pouvoir). Ce qui grince se joue dans la lutte de contrôle : ce courage peut glisser vers des rapports de force autour de l'intimité ou des ressources, utiliser l'intensité pour garder la main, avoir du mal à lâcher un conflit une fois engagé. La leçon à emporter est que le courage n'a pas besoin de conflit pour se prouver.",
    9: "Mars en maison IX canalise l'énergie vers la conviction, la croyance et l'exploration : une vraie passion pour les idées et les grandes causes, un désir réel d'agir au nom de ce en quoi on croit. Ce qui coûte le plus se joue dans le dogmatisme combatif : cette conviction peut chercher le combat idéologique plutôt que l'échange, pousser à des décisions impulsives au nom de la liberté ou d'une croyance. Grandir ici, c'est apprendre qu'une conviction n'a pas besoin de conquérir les autres visions pour rester solide.",
    10: "Mars en maison X pousse vers l'ambition et la réussite visible : une vraie combativité professionnelle, un courage réel pour viser des objectifs publics, une énergie qui n'aime pas se contenter de peu. Le point sensible se loge dans l'ambition agressive : cette énergie peut créer des conflits avec l'autorité ou la concurrence, épuiser à force de courir après la reconnaissance. Ce qu'il y a à travailler est qu'une ambition tenue dans la durée porte plus loin qu'une ambition précipitée.",
    11: "Mars en maison XI canalise l'énergie dans l'action collective : une vraie combativité au service d'une cause, une énergie qui se sent stimulée par le groupe et l'objectif commun. Le revers se joue dans le conflit interne au groupe : cette énergie peut créer des tensions sur la direction à prendre, s'impatienter du rythme collectif, se battre pour une cause au détriment des gens qui la portent. Le terrain de maturation est d'apprendre qu'une cause n'est solide que grâce aux gens qui restent pour la porter.",
    12: "Mars en maison XII tourne l'énergie vers l'intérieur ou l'invisible : une force qui s'exprime discrètement ou indirectement, un courage réel dans des combats privés, démons intérieurs, travail invisible de personne ne voit. La difficulté se niche dans la colère non exprimée : cette énergie contenue peut ressortir de façon détournée, se retourner contre soi-même en sabotage, épuiser dans des combats que personne d'autre ne connaît. Ce qui aide à mûrir ici est de saisir que certains combats ont besoin d'être mis au jour pour être vraiment gagnés.",
  },
  saturn: {
    1: "Saturne en maison I construit l'identité par la discipline et la maîtrise de soi : une présence réservée, souvent sérieuse, avec une maturité qui s'impose parfois tôt dans la vie et une vraie capacité à porter des responsabilités avant l'heure. Le revers se joue dans la rigidité : cette identité si construite peut se figer en armure, redouter de montrer la moindre faille ou incompétence, se juger durement avant que personne d'autre ne le fasse. Ce qu'il y a à intégrer est que le sérieux n'a pas besoin d'être une armure à chaque instant.",
    2: "Saturne en maison II construit une relation disciplinée et prudente à l'argent : une sécurité matérielle bâtie lentement mais durablement, un vrai sens des responsabilités financières. Le point sensible se loge dans la peur du manque : cette prudence peut persister même quand les ressources sont largement suffisantes, faire dépendre la valeur personnelle de ce qu'on a gagné à la sueur de son front. Le terrain de maturation est d'apprendre qu'une sécurité construite patiemment n'a pas besoin d'être sans cesse remise à l'épreuve pour être fiable.",
    3: "Saturne en maison III donne un esprit structuré et sérieux : une pensée disciplinée, une vraie rigueur dans l'apprentissage et la communication, parfois plus lente mais réellement approfondie. Ce qui coûte le plus se joue dans le doute sur soi : cette rigueur peut masquer une peur de ne pas être compris ou pris au sérieux, une relation formelle et distante avec la fratrie ou le voisinage. Ce qu'il y a à travailler est que comprendre n'a pas besoin d'être instantané pour être réel.",
    4: "Saturne en maison IV porte un rapport pesant ou très structuré au foyer : une vraie responsabilité envers la famille, parfois assumée tôt, des fondations bâties à force d'efforts réels plutôt qu'offertes. La difficulté se niche dans la froideur héritée : ce sens du devoir peut reproduire une distance affective transmise par la famille, faire porter le poids d'une charge familiale, rendre difficile de se sentir vraiment chez soi quelque part. Grandir ici, c'est apprendre qu'un foyer construit à l'effort reste un vrai foyer.",
    5: "Saturne en maison V aborde la créativité, l'amour et le jeu avec prudence et discipline : ce qui est créé dure dans le temps, mais il faut d'abord se sentir en sécurité pour oser vraiment jouer ou aimer sans retenue. Ce qui coince se joue dans l'autocritique : cette prudence peut juger sévèrement le moindre geste créatif, laisser la peur de l'échec bloquer la spontanéité et la joie. Le vrai travail consiste à apprendre qu'une création n'a pas besoin d'être parfaite pour avoir de la valeur.",
    6: "Saturne en maison VI construit une vraie maîtrise par l'effort quotidien : discipline dans le travail et la routine, exigence élevée envers soi-même, une compétence qui se bâtit avec constance plutôt qu'avec facilité. Le prix à payer se loge dans le surmenage : cette discipline peut basculer vers un jugement sévère sur sa propre productivité, une tension physique née d'une responsabilité chroniquement portée. Ce qui aide à mûrir ici est de saisir que le repos n'a pas besoin d'être mérité pour être légitime.",
    7: "Saturne en maison VII prend le partenariat au sérieux : un vrai engagement, un sens réel de la responsabilité envers la relation, souvent des partenaires plus mûrs ou des liens qui s'approfondissent avec le temps plutôt que dans l'urgence. La tension se noue dans la peur de l'engagement : cette prise au sérieux peut, paradoxalement, retarder le pas vers la relation, installer une froideur ou une distance affective, faire choisir le devoir plutôt qu'une vraie intimité. La leçon à emporter est que la proximité n'a pas besoin d'être contrôlée pour rester sûre.",
    8: "Saturne en maison VIII affronte la crise, la transformation et les ressources partagées avec une discipline et un courage réels : une vraie maîtrise face à ce qui est habituellement redouté, une capacité à traverser l'épreuve avec structure plutôt qu'à la fuir. Ce qui grince se joue dans le besoin de contrôle : ce courage peut se transformer en peur de perdre la maîtrise dans l'intimité ou la crise, en difficulté à faire confiance à d'autres avec sa vulnérabilité. Le terrain de maturation est d'apprendre que la confiance n'exige pas le contrôle.",
    9: "Saturne en maison IX construit une vision du monde solide et éprouvée : une approche disciplinée de la croyance, de la philosophie et des études supérieures, une conviction qui se bâtit avec le temps plutôt que par enthousiasme passager. Le revers se joue dans la rigidité de pensée : cette solidité peut glisser vers le dogmatisme, la peur d'avoir tort en public, des convictions tenues comme une protection contre l'incertitude plutôt que comme une vraie recherche. Ce qu'il y a à intégrer est qu'une conviction solide peut supporter d'être questionnée.",
    10: "Saturne est chez lui en maison X : la carrière et la réputation se construisent avec une vraie maîtrise, une discipline et une ambition de long terme, souvent une réussite gagnée à force d'efforts plutôt qu'offerte. Le point sensible se loge dans la dépendance à la réussite : cette identité si construite par l'accomplissement peut s'effondrer sans reconnaissance professionnelle, se juger durement au moindre échec public. Ce qu'il y a à travailler est que la valeur personnelle ne dépend pas uniquement du titre gagné.",
    11: "Saturne en maison XI construit des amitiés prudentes et engagées : moins nombreuses mais souvent plus durables, un vrai sens des responsabilités envers les causes et les collectifs choisis avec soin. Ce qui coûte le plus se joue dans la méfiance envers le groupe : cette prudence peut créer un sentiment de solitude malgré des liens réels, une peur de ne jamais vraiment appartenir même au sein d'un cercle choisi. Grandir ici, c'est apprendre qu'appartenir vraiment ne demande pas d'être indispensable au groupe.",
    12: "Saturne en maison XII tourne la discipline vers l'intérieur : une responsabilité vécue en privé, une vraie force construite dans la solitude ou une épreuve invisible, souvent le poids de charges que personne d'autre ne voit. La difficulté se niche dans l'isolement : cette discipline intérieure peut nourrir la peur d'être vraiment vu, des tendances à s'auto-punir en silence plutôt qu'à demander de l'aide. Ce qui aide à mûrir ici est de saisir que certains fardeaux s'allègent une fois partagés.",
  },
  fortune: {
    1: "La Part de Fortune en maison I déclenche le bien-être dans la présence elle-même : être simplement soi, sans calcul ni stratégie, suffit souvent à attirer une aisance naturelle dans la façon dont on est perçu et accueilli. Le piège se loge dans l'excès de confiance : cette facilité de premier abord peut pousser à ne compter que sur le charme naturel, sans jamais aller plus loin pour concrétiser ce qu'il ouvre. Ce qu'il y a à intégrer est que cette aisance est un point de départ à cultiver, pas une stratégie suffisante à elle seule.",
    2: "La Part de Fortune en maison II déclenche le bien-être dans un rapport naturellement fluide à l'argent et aux ressources : gagner sa vie, faire fructifier ce qu'on possède, semble couler avec moins de friction que pour d'autres. Le piège se niche dans la négligence : cette aisance financière peut pousser à croire que les choses « s'arrangeront toujours », sans jamais vraiment gérer activement ce qui, justement, se construit facilement. Le terrain de maturation est d'apprendre à entretenir ce que cette facilité apporte plutôt qu'à le tenir pour acquis.",
    3: "La Part de Fortune en maison III déclenche le bien-être dans l'échange quotidien : parler, apprendre, se relier à la fratrie ou au voisinage semble naturellement facile, presque sans effort conscient. Le piège se loge dans la facilité non exploitée : cette aisance de la parole peut suffire à elle seule sans jamais être approfondie par la pratique ou la persévérance qu'elle mériterait. Ce qu'il y a à travailler est que ce don naturel pour l'échange reste un avantage de départ, pas un aboutissement.",
    4: "La Part de Fortune en maison IV déclenche le bien-être dans le foyer et les racines : la sécurité affective, le sentiment d'appartenance familiale, s'installent avec une facilité que d'autres maisons n'offrent pas. Le piège se niche dans la présomption : cette stabilité peut faire oublier qu'un foyer, même naturellement accueillant, a besoin d'attention continue pour le rester. La leçon à emporter est de prendre soin activement de cette base plutôt que de supposer qu'elle se maintiendra d'elle-même.",
    5: "La Part de Fortune en maison V déclenche le bien-être dans la créativité, l'amour et le plaisir : les projets créatifs, les histoires de cœur, semblent portés par une chance réelle, une facilité à être vu et apprécié. Le piège se loge dans l'attente déçue : cette aisance peut faire croire que l'amour ou le succès créatif devraient toujours venir sans effort, avec un vrai découragement dès qu'un peu de travail s'impose. Ce qu'il y a à intégrer est que ce don naturel mérite d'être exercé, pas seulement constaté.",
    6: "La Part de Fortune en maison VI déclenche le bien-être dans le travail quotidien, la santé et l'utilité : les routines se mettent en place avec une facilité relative, le corps semble naturellement plus équilibré. Le piège se niche dans le relâchement : cette aisance peut faire croire qu'aucun entretien n'est nécessaire, précisément parce qu'elle a toujours été là sans effort particulier. Le terrain de maturation est de considérer cette facilité comme une ressource à protéger par un soin régulier, pas comme une preuve qu'elle n'en a pas besoin.",
    7: "La Part de Fortune en maison VII déclenche le bien-être dans le partenariat : coopérer, s'associer, avancer à deux semble venir avec une aisance relationnelle réelle. Le piège se loge dans l'attente passive : cette facilité peut pousser à attendre que le bon partenaire ou collaborateur se présente de lui-même, sans jamais vraiment s'investir pour le faire advenir. Ce qu'il y a à travailler est que cette aisance relationnelle est un cadeau à construire par une réciprocité réelle, pas seulement à espérer.",
    8: "La Part de Fortune en maison VIII fonctionne différemment des autres maisons : le bien-être ne se trouve pas dans la facilité de surface mais dans la capacité à traverser vraiment ce qui touche aux ressources partagées, à l'intimité, à la transformation. Le piège se niche dans le raccourci : cette recherche d'aisance peut pousser à chercher des réponses faciles à ce qui demande en réalité une vraie profondeur, en utilisant le charme pour éviter la transformation nécessaire. La leçon à intégrer est que l'aisance ici se trouve en traversant la profondeur, pas en la contournant.",
    9: "La Part de Fortune en maison IX déclenche le bien-être dans l'exploration, l'apprentissage, les croyances et les horizons lointains : voyager, apprendre, transmettre du sens semble venir avec une facilité réelle. Le piège se loge dans l'évasion sans ancrage : cette aisance exploratoire peut servir à fuir plutôt qu'à vraiment grandir, en traitant chaque nouvel horizon comme une échappatoire plutôt qu'un approfondissement. Ce qu'il y a à intégrer est de suivre cet attrait pour le lointain jusqu'au bout, avec un engagement réel envers ce qui est appris.",
    10: "La Part de Fortune en maison X déclenche le bien-être dans la carrière et la reconnaissance publique : la réussite professionnelle, la réputation, semblent venir avec moins de friction que pour d'autres. Le piège se niche dans la minimisation : cette aisance peut pousser à attendre une reconnaissance qui arrive sans effort visible, ou à sous-estimer un vrai succès en le mettant sur le compte de la seule chance. La leçon à emporter est de reconnaître pleinement la réussite que cette aisance apporte, plutôt que de la relativiser.",
    11: "La Part de Fortune en maison XI déclenche le bien-être dans les amitiés, les collectifs et les causes partagées : appartenir à un groupe, se sentir soutenu, vient avec une facilité relationnelle réelle. Le piège se loge dans l'attente sans investissement : cette aisance peut faire croire que le soutien collectif arrivera de lui-même, sans jamais vraiment s'investir dans les liens qui le rendent possible. Ce qu'il y a à travailler est de cultiver cette aisance naturelle par une présence constante, pas seulement par une disponibilité de circonstance.",
    12: "La Part de Fortune en maison XII déclenche le bien-être dans le retrait, la spiritualité, la compassion et le lâcher-prise : la solitude choisie, l'introspection, semblent apporter un apaisement réel et naturel. Le piège se niche dans l'évasion déguisée en repos : ce retrait facile peut servir à fuir ce qui demanderait d'être affronté plutôt qu'à vraiment se ressourcer. Le terrain de maturation est de faire de ce retrait une restauration authentique, pas un évitement.",
  },
  jupiter: {
    1: "Jupiter en maison I déborde sur l'image donnée : la présence occupe naturellement de la place, avec une confiance et un optimisme qui se lisent souvent dans la carrure, la voix ou la façon d'entrer dans une pièce, on est vu comme quelqu'un « en plus grand » avant même d'avoir dit quoi que ce soit. Ce qui coince se joue dans la mesure : cette expansion spontanée peut déborder en promesses trop généreuses, en confiance qui frôle l'excès, ou en une présence si large qu'elle laisse peu d'espace à ceux d'à côté. L'ampleur n'a pourtant pas besoin d'être maximale à chaque instant pour rester réelle : on peut occuper sa place sans occuper toute la pièce.",
    2: "Jupiter en maison II donne un rapport large à l'argent et à ce qui rassure matériellement : la confiance qu'il y en aura toujours assez, une générosité naturelle, souvent une vraie capacité à attirer ou faire fructifier les ressources sans s'en inquiéter constamment. Le revers se loge dans l'évaluation : cet optimisme peut désaligner les dépenses des moyens réels, surestimer ce qu'on possède ou ce qu'un projet va rapporter, jusqu'à confondre confiance et imprudence. Ce qu'il y a à intégrer est qu'un chiffre précis ne trahit pas l'abondance ressentie, que la prudence budgétaire peut coexister avec la générosité plutôt que la contredire.",
    3: "Jupiter en maison III élargit tout ce qui touche à la parole et à l'entourage proche : curiosité tous azimuts, enthousiasme communicatif, une facilité à faire des liens entre des idées ou des personnes qui semblaient éloignées. Le prix à payer se loge dans la précision : cette générosité de pensée peut déraper en généralisations hâtives, en promesses verbales qui dépassent ce qui sera vraiment tenu, ou en une conversation si tournée vers les grandes idées qu'elle perd le détail concret. Le travail consiste à apprendre que dire moins, mais juste, porte parfois plus loin qu'un enthousiasme qui embrasse tout sans vérifier.",
    4: "Jupiter en maison IV colore le foyer et les racines d'une tonalité généreuse : une maison qui accueille largement, une famille vécue comme une ressource morale ou philosophique autant qu'affective, parfois littéralement un foyer nombreux ou en expansion. La tension se noue dans l'idéalisation : ce besoin de voir grand dans les racines peut enjoliver une histoire familiale plus compliquée qu'elle n'y paraît, ou créer une attente irréaliste de ce qu'un foyer doit apporter. Le terrain de maturation est d'apprendre à aimer ses racines telles qu'elles sont réellement, pas seulement dans la version agrandie qu'on préférerait raconter.",
    5: "Jupiter en maison V amplifie le plaisir, la créativité et l'amour ludique : une capacité réelle à jouer, créer et aimer sans retenue, souvent une chance perçue dans les histoires de cœur ou les projets créatifs, et un rapport généreux aux enfants quand il y en a. Ce qui grince se joue dans la mesure du plaisir : cet appétit peut déraper en excès (dépenses, promesses amoureuses, prises de risque) pris pour de la joie de vivre plutôt que pour ce qu'ils sont. Le vrai travail consiste à apprendre que le plaisir n'a pas besoin d'être démesuré pour être pleinement ressenti.",
    6: "Jupiter en maison VI cherche du sens jusque dans le quotidien : le travail et les routines fonctionnent mieux quand ils s'inscrivent dans une perspective plus large qu'une simple tâche à accomplir, une mission, un apprentissage, une progression. La tension se loge dans la discipline : cette quête de sens peut rendre les détails répétitifs pesants, pousser à trop en promettre professionnellement ou à négliger un corps qu'on croit indestructible tant qu'on se sent porté par l'élan. Ce qu'il y a à travailler est d'apprendre que la routine bien tenue est elle-même une forme de croissance, pas son contraire.",
    7: "Jupiter en maison VII fait du partenaire une figure d'ouverture : l'autre est souvent vécu comme celui ou celle qui fait grandir, élargit l'horizon, apporte une philosophie ou une culture différente, l'engagement se choisit en partie pour ce qu'il permet de devenir. Ce qui coûte le plus se joue dans l'idéalisation : cette attente peut placer la barre trop haut, chercher un partenaire « plus grand que nature » au point de ne jamais se satisfaire de quelqu'un de réel, ou surestimer la compatibilité au moment de s'engager. Le terrain de maturation est d'apprendre à faire grandir la relation elle-même plutôt que d'attendre que l'autre s'en charge seul.",
    8: "Jupiter en maison VIII aborde les crises, les ressources partagées et l'intimité profonde avec une confiance rare pour cette maison habituellement redoutée : une capacité à traverser les épreuves en y trouvant du sens, parfois une chance réelle avec l'argent des autres (héritage, association, dette bien gérée). Ce qui coince se loge dans l'évitement : cet optimisme peut servir à contourner ce qui fait vraiment mal, une positivité de façade qui empêche de vraiment traverser le deuil, la jalousie ou la peur plutôt que de les transformer. Ce qu'il y a à intégrer est que la foi en la traversée ne dispense pas de la vivre pleinement.",
    9: "Jupiter est chez lui en maison IX : philosophie, études supérieures, voyages et croyances personnelles s'articulent naturellement, avec une soif réelle de sens et d'horizon qui dépasse le quotidien, c'est souvent ici que se construit une vision du monde structurante pour toute une vie. Le point sensible se loge dans la certitude : cette conviction peut glisser vers le dogmatisme, l'impression de détenir une vérité plus large que celle des autres, ou une générosité d'idées qui tolère mal la contradiction. Grandir ici consiste à apprendre que la vraie ouverture d'esprit accepte d'être questionnée, pas seulement de questionner.",
    10: "Jupiter en maison X porte la réputation et la carrière vers l'ampleur : une reconnaissance publique souvent facilitée, un charisme qui inspire confiance, une ambition qui vise large plutôt que de se contenter d'un poste modeste. Le revers se joue dans la solidité : cette expansion peut aller plus vite que les fondations réelles, avec des engagements professionnels pris avant d'avoir les moyens de les tenir, ou une image publique plus grande que ce qui la soutient concrètement. Le terrain de maturation est d'apprendre à construire une réussite qui tient dans la durée, pas seulement dans l'élan du moment.",
    11: "Jupiter en maison XI élargit le réseau social et les idéaux collectifs : un cercle d'amis souvent large et varié, un vrai enthousiasme pour les causes et les projets de groupe, la conviction que l'avenir se construit collectivement. La difficulté se niche dans la profondeur : cette générosité relationnelle peut rester en surface, multiplier les connaissances sans vraiment approfondir les liens, ou idéaliser un groupe ou une cause au point d'en ignorer les failles réelles. Ce qu'il y a à travailler est de choisir, parmi toutes les directions possibles, celles qui méritent un engagement réellement suivi.",
    12: "Jupiter en maison XII loge la confiance et le sens dans l'invisible : une foi intérieure, spirituelle ou intuitive, qui soutient même quand rien de concret ne la justifie, parfois une chance discrète qui agit en coulisses plutôt qu'au grand jour. Ce qui coince se joue dans l'évitement : cet optimisme peut servir à fuir ce qui est réellement caché ou douloureux, une spiritualité utilisée pour survoler plutôt que pour affronter ce que cette maison demande de regarder en face. Ce qu'il y a à travailler est que la foi la plus solide est celle qui a traversé l'ombre, pas celle qui l'a évitée.",
  },
  uranus: {
    1: "Uranus en maison I rend l'identité imprévisible et résolument singulière : une présence qui surprend, qui refuse d'entrer dans un moule, avec souvent des changements de look ou d'attitude soudains qui déroutent l'entourage. Ce qui coûte le plus se joue dans l'instabilité de l'image : cette singularité si affirmée peut virer à la provocation gratuite, changer de visage juste pour se distinguer, ou empêcher de se sentir stable dans sa propre peau. Ce qu'il y a à intégrer est que l'originalité n'a pas besoin d'être permanente pour rester vraie.",
    2: "Uranus en maison II donne un rapport instable et original à l'argent : les revenus peuvent varier de façon soudaine, une vraie allergie à toute dépendance financière, parfois une source de gains inattendue ou peu conventionnelle. Le revers se joue dans l'insécurité chronique : cette instabilité peut nourrir une anxiété permanente sur les ressources, ou pousser à rompre un cadre stable juste pour préserver sa liberté, même quand ce cadre servait bien. Grandir ici, c'est apprendre que la sécurité matérielle et la liberté ne sont pas nécessairement incompatibles.",
    3: "Uranus en maison III donne un esprit électrique et non conformiste : des idées qui surgissent par éclairs, un vrai talent pour voir un sujet sous un angle que personne n'avait envisagé, parfois une relation à la fratrie ou au voisinage marquée par la distance ou la rupture. Le point sensible se loge dans la nervosité mentale : cette vivacité peut sauter d'une idée à l'autre sans jamais se poser, ou provoquer pour le plaisir de bousculer plutôt que pour vraiment échanger. Le terrain de maturation est d'apprendre qu'une idée originale gagne à être partagée posément pour vraiment porter.",
    4: "Uranus en maison IV bouscule le rapport au foyer et aux racines : des déménagements fréquents ou soudains, une famille peu conventionnelle, parfois une rupture précoce avec le cadre familial d'origine pour affirmer sa propre voie. La tension se noue dans le déracinement : ce besoin d'indépendance peut empêcher de se sentir vraiment chez soi où que ce soit, ou pousser à fuir toute racine par peur d'y être enfermé. Ce qu'il y a à travailler est qu'un foyer peut se réinventer sans devoir être totalement rejeté.",
    5: "Uranus en maison V rend la créativité et l'amour résolument hors norme : une inspiration qui frappe sans prévenir, des attirances soudaines ou électriques, un vrai besoin de liberté dans le jeu et la création. Le prix à payer se loge dans l'instabilité affective : cette électricité peut rendre difficile un engagement amoureux dans la durée, pousser à rompre dès que la relation devient trop prévisible, transformer chaque histoire en coup de foudre suivi d'une fuite. La leçon à emporter est qu'aimer librement ne signifie pas devoir fuir dès que ça devient sérieux.",
    6: "Uranus en maison VI apporte une énergie nerveuse et innovante au travail quotidien : une vraie aptitude à réinventer une méthode, une allergie profonde à la routine figée, parfois un système nerveux sensible qui réagit vite au stress. La difficulté se niche dans l'instabilité professionnelle : ce besoin de changement peut pousser à quitter un poste dès qu'il devient trop prévisible, ou générer une tension physique liée à l'impatience chronique. Le vrai travail consiste à apprendre qu'une routine peut inclure de la nouveauté sans devoir être abandonnée entièrement.",
    7: "Uranus en maison VII attire des partenariats hors norme : des partenaires souvent atypiques, indépendants ou imprévisibles, un engagement vécu différemment des attentes conventionnelles. Ce qui grince se joue dans l'instabilité relationnelle : ce besoin de liberté peut provoquer des ruptures soudaines dès que la relation semble trop contraignante, ou attirer des liens qui ne durent jamais assez pour vraiment s'approfondir. Ce qui aide à mûrir ici est de saisir qu'un partenariat peut respecter la liberté de chacun sans devoir rester à distance.",
    8: "Uranus en maison VIII traverse les crises et les ressources partagées par des ruptures soudaines : des bouleversements financiers ou intimes qui arrivent sans prévenir, une vraie capacité à se réinventer complètement après un choc. Ce qui coince se joue dans l'imprévisibilité de l'intimité : cette électricité peut rendre difficile une vulnérabilité stable dans le temps, ou pousser à fuir une intimité dès qu'elle devient trop profonde. Ce que ce placement invite à comprendre est qu'une transformation n'a pas besoin d'être brutale pour être réelle.",
    9: "Uranus en maison IX bouscule les croyances et la vision du monde : une pensée qui rejette les dogmes reçus, un attrait réel pour des philosophies ou des cultures radicalement différentes, parfois une conversion soudaine à une vision nouvelle. Ce qui coûte le plus se joue dans l'instabilité des convictions : ce besoin de rupture intellectuelle peut faire changer de croyance aussi vite qu'on l'avait adoptée, ou rejeter une idée simplement parce qu'elle est devenue familière. Ce qu'il y a à intégrer est qu'une conviction peut évoluer sans devoir être abandonnée à chaque nouvelle idée séduisante.",
    10: "Uranus en maison X marque la carrière et la réputation du sceau de l'imprévu : des changements de voie soudains, une vraie vocation à innover ou à bousculer un secteur, une réussite qui suit rarement un chemin conventionnel. Le revers se joue dans l'instabilité professionnelle : ce besoin d'indépendance peut provoquer des ruptures de carrière répétées, ou entrer en conflit ouvert avec toute autorité perçue comme rigide. Grandir ici, c'est apprendre qu'une trajectoire peut rester fidèle à soi sans devoir tout renverser à chaque étape.",
    11: "Uranus est chez lui en maison XI : les amitiés, les causes collectives et la vision d'avenir s'expriment avec une aisance naturelle, souvent un vrai talent pour rassembler des gens différents autour d'une idée nouvelle. Le point sensible se loge dans le détachement : cette aisance collective peut rester en surface, garder une distance émotionnelle même au sein d'un groupe proche, privilégier l'idéal du groupe à la relation réelle avec chacun de ses membres. Le terrain de maturation est d'apprendre qu'appartenir à un collectif n'exige pas de sacrifier sa proximité avec les individus qui le composent.",
    12: "Uranus en maison XII loge le besoin de rupture dans l'invisible : des intuitions soudaines, une vie intérieure marquée par des prises de conscience brutales, parfois un sentiment de décalage profond avec le monde qui ne se dit jamais vraiment. La tension se noue dans l'isolement choisi : ce besoin de liberté intérieure peut couper de tout ancrage extérieur, nourrir un sentiment de ne jamais vraiment appartenir nulle part. Ce qu'il y a à travailler est qu'une part de soi peut rester libre sans devoir se couper complètement du monde partagé.",
  },
  neptune: {
    1: "Neptune en maison I rend l'image insaisissable et poreuse : une présence qui semble se fondre dans l'ambiance du moment, une sensibilité empathique qui se lit dès le premier regard, parfois une identité difficile à cerner même pour soi-même. La tension se noue dans la dilution : cette porosité peut effacer les contours de qui l'on est face aux attentes des autres, ou faire dépendre l'image de soi de ce que chacun projette dessus. Ce qu'il y a à travailler est qu'une identité peut rester fluide sans devoir se dissoudre complètement dans le regard d'autrui.",
    2: "Neptune en maison II brouille le rapport concret à l'argent : une intuition réelle pour ce qui a de la valeur au-delà du chiffre, parfois un flou chronique sur les questions matérielles, une générosité qui peut confiner à l'imprécision budgétaire. Le prix à payer se loge dans le déni financier : cette confusion peut faire ignorer une réalité matérielle inconfortable plutôt que de l'affronter, ou pousser à idéaliser une source de revenus qui n'existe pas vraiment. La leçon à emporter est qu'un idéal de valeur mérite d'être vérifié par des chiffres réels, sans que cela le trahisse.",
    3: "Neptune en maison III donne une pensée intuitive et imagée : des idées qui viennent par association ou par image plutôt que par logique linéaire, une vraie sensibilité poétique dans la parole, parfois une communication avec la fratrie ou le voisinage marquée par le non-dit. La difficulté se niche dans l'imprécision : cette pensée si fluide peut avoir du mal à se structurer clairement, laisser place au malentendu faute d'avoir été exprimée avec assez de netteté. Le vrai travail consiste à apprendre qu'une intuition gagne en force quand elle trouve les mots pour se dire clairement.",
    4: "Neptune en maison IV enveloppe le foyer et les racines d'un flou particulier : une atmosphère familiale sensible, parfois marquée par un secret, une absence ou un non-dit qui colore durablement le sentiment de sécurité. Ce qui grince se joue dans l'idéalisation du passé familial : ce flou peut nourrir une image enjolivée ou au contraire trouble de l'histoire familiale, difficile à démêler du ressenti réel. Ce qui aide à mûrir ici est de saisir qu'un foyer intérieur solide peut se construire même sans avoir toutes les réponses sur celui d'origine.",
    5: "Neptune en maison V inspire une créativité et un amour teintés de rêve : une imagination artistique réelle, une tendance à idéaliser l'être aimé ou le projet créatif en cours, un romantisme qui cherche la fusion plus que la réalité concrète de l'autre. Ce qui coince se joue dans l'illusion amoureuse : cet idéal peut faire voir chez un partenaire ou dans une création ce qui n'y est pas vraiment, jusqu'à une désillusion douloureuse quand la réalité rattrape le rêve. Ce que ce placement invite à comprendre est qu'aimer vraiment demande de voir l'autre tel qu'il est, pas seulement tel qu'on voudrait qu'il soit.",
    6: "Neptune en maison VI lie le quotidien à une quête de sens plus large : un vrai besoin de servir une cause qui dépasse la simple tâche à accomplir, une sensibilité corporelle qui capte facilement le stress ambiant sous forme de fatigue diffuse ou de symptômes difficiles à nommer. Ce qui coûte le plus se joue dans le sacrifice de soi : ce besoin de service peut mener à s'oublier complètement dans le travail ou le soin des autres, ignorer des limites corporelles réelles jusqu'à l'épuisement. Ce qu'il y a à intégrer est que prendre soin des autres suppose d'abord d'écouter ce que le corps réclame.",
    7: "Neptune en maison VII idéalise le partenariat : l'autre est souvent perçu comme une âme sœur, un partenaire choisi pour ce qu'il inspire ou incarne plutôt que pour ce qu'il est concrètement au quotidien. Le revers se joue dans la désillusion relationnelle : cette idéalisation peut masquer des signaux réels chez un partenaire, ou installer une attente de fusion totale impossible à tenir dans la durée. Grandir ici, c'est apprendre qu'un amour réel se construit avec les failles de l'autre, pas seulement avec l'idéal qu'il inspire au départ.",
    8: "Neptune en maison VIII plonge l'intimité et les ressources partagées dans une zone trouble : une intuition puissante pour ce qui reste non-dit dans les liens profonds, parfois une confusion sur ce qui appartient vraiment à soi ou à l'autre dans une relation fusionnelle. Le point sensible se loge dans la perte de limites : cette porosité peut rendre difficile de distinguer ses propres besoins de ceux du partenaire dans l'intimité ou les finances communes, jusqu'à s'y perdre complètement. Le terrain de maturation est d'apprendre qu'une intimité profonde peut se vivre sans dissoudre entièrement ses propres frontières.",
    9: "Neptune en maison IX élargit la quête de sens jusqu'au mysticisme : une vraie attirance pour le spirituel, les grandes croyances, une philosophie qui cherche moins à comprendre qu'à ressentir une vérité plus vaste. La tension se noue dans l'évasion idéologique : cette quête peut servir à fuir le réel plutôt qu'à l'éclairer, adopter une croyance pour échapper à une vie jugée trop ordinaire plutôt que pour vraiment y croire. Ce qu'il y a à travailler est qu'une spiritualité solide s'ancre dans le quotidien, elle ne s'y substitue pas.",
    10: "Neptune en maison X rend la carrière et la réputation publiques floues ou inspirées : une vocation souvent tournée vers l'art, le soin ou le service, parfois une image publique difficile à cerner nettement, ou une réussite qui semble se dérober juste avant d'être atteinte. Le prix à payer se loge dans le manque de direction : cet idéal professionnel peut rester au stade du rêve faute de structure concrète pour le porter, ou se laisser guider par une image trop vague de ce que la réussite devrait être. La leçon à emporter est qu'une vocation inspirée a besoin d'étapes concrètes pour ne pas rester un simple horizon.",
    11: "Neptune en maison XI porte les idéaux collectifs et les causes humanitaires : un vrai besoin d'appartenir à quelque chose qui dépasse l'intérêt individuel, une empathie réelle pour des causes larges, parfois des amitiés choisies pour ce qu'elles incarnent plutôt que pour ce qu'elles sont vraiment. La difficulté se niche dans la désillusion collective : cet idéal peut mener à idéaliser un groupe ou une cause au point d'en ignorer les failles réelles, jusqu'à une déception profonde quand la réalité du collectif rattrape le rêve porté sur lui. Le vrai travail consiste à apprendre qu'une cause reste solide même vue avec ses imperfections réelles.",
    12: "Neptune est chez lui en maison XII : la vie intérieure, l'intuition et le sens du sacré y trouvent leur terrain le plus naturel, avec une porosité réelle à ce qui échappe au rationnel, rêves, art, compassion, spiritualité. Ce qui grince se joue dans la dissolution de soi : cette porosité peut effacer les limites entre soi et le monde au point de se perdre, fuir le réel par le rêve, le sommeil ou d'autres formes d'évasion plutôt que d'affronter ce qui doit l'être. Ce qui aide à mûrir ici est de saisir qu'un retrait intérieur nourrit vraiment quand il reste relié, même ténuement, au monde partagé.",
  },
  pluto: {
    1: "Pluton en maison I donne une présence intense et magnétique : un regard qui semble voir au-delà des apparences, une aura de pouvoir ou de mystère qui s'impose sans effort apparent, une identité forgée par des passages transformateurs plutôt que par un développement tranquille. Ce qui grince se joue dans le contrôle de l'image : cette intensité peut pousser à vouloir tout maîtriser dans la façon dont on est perçu, ou intimider sans le vouloir des personnes qui hésitent alors à s'approcher vraiment. Ce qui aide à mûrir ici est de saisir qu'une présence puissante peut aussi se rendre accessible sans rien perdre de sa profondeur.",
    2: "Pluton en maison II transforme le rapport à l'argent et aux ressources en enjeu de pouvoir : une capacité réelle à reconstruire une sécurité matérielle après une perte totale, parfois des crises financières qui obligent à tout repenser depuis zéro. Ce qui coince se joue dans le contrôle matériel : cette intensité peut faire de l'argent un outil de pouvoir sur soi ou sur les autres, nourrir une peur profonde du manque même quand les ressources sont largement suffisantes. Ce que ce placement invite à comprendre est qu'une sécurité vraiment solide ne dépend pas du contrôle total de ce qu'on possède.",
    3: "Pluton en maison III donne un esprit pénétrant qui va toujours chercher sous la surface : une conversation qui évite le superficiel, un vrai talent pour percer les non-dits dans les échanges, parfois des relations avec la fratrie ou le voisinage marquées par des rapports de pouvoir ou des secrets tus. Ce qui coûte le plus se joue dans la méfiance verbale : cette perspicacité peut virer au soupçon systématique sur les intentions des autres dans une conversation pourtant anodine. Ce qu'il y a à intégrer est que toutes les paroles n'ont pas une intention cachée à décoder.",
    4: "Pluton en maison IV plonge le foyer et les origines dans une intensité rare : une histoire familiale souvent marquée par un secret, une crise majeure ou un pouvoir exercé de façon écrasante par une figure parentale, dont la transformation devient une tâche de toute une vie. Le revers se joue dans la reproduction du contrôle : ce poids hérité peut pousser à reproduire, sans le vouloir, la même dynamique de pouvoir dans son propre foyer, ou nourrir une méfiance profonde envers l'idée même de sécurité familiale. Grandir ici, c'est apprendre qu'un héritage familial lourd peut être transformé plutôt que simplement répété.",
    5: "Pluton en maison V vit la créativité et l'amour avec une intensité totale : rien n'est fait à moitié, ni une passion créative, ni un amour, avec une vraie capacité à se réinventer complètement à travers ce qu'on aime ou ce qu'on crée. Le point sensible se loge dans la possessivité : cette intensité peut glisser vers un besoin de contrôle sur le partenaire ou l'œuvre créée, une jalousie qui naît de la peur de perdre ce qui compte le plus. Le terrain de maturation est d'apprendre qu'aimer intensément n'exige pas de tout maîtriser chez ce qu'on aime.",
    6: "Pluton en maison VI transforme le rapport au travail et au corps en profondeur : une capacité réelle à se réinventer professionnellement après une crise, une intuition corporelle aiguë sur ce qui doit changer avant que la santé ne l'impose de force. La tension se noue dans l'obsession du contrôle quotidien : cette intensité peut virer à un perfectionnisme rigide dans le travail ou une surveillance excessive du corps, jusqu'à un épuisement né du besoin de tout maîtriser. Ce qu'il y a à travailler est qu'un vrai changement de fond n'a pas besoin d'un contrôle total pour advenir.",
    7: "Pluton en maison VII fait du partenariat un terrain de transformation profonde : des relations rarement tièdes, souvent marquées par une intensité, une fascination ou des rapports de pouvoir qui obligent à grandir. Le prix à payer se loge dans la lutte de pouvoir : cette intensité peut transformer la relation en bras de fer permanent, nourrir la jalousie ou le besoin de contrôler l'autre par peur de le perdre. La leçon à emporter est qu'un partenariat transformateur reste sain seulement s'il laisse à chacun sa propre souveraineté.",
    8: "Pluton est chez lui en maison VIII : les crises, les ressources partagées et la transformation profonde s'y expriment avec une puissance rare, une vraie capacité à traverser ce qui briserait d'autres placements et à en ressortir régénéré. La difficulté se niche dans l'intensité difficile à partager : cette force peut se refermer sur elle-même, se méfier d'une vulnérabilité pourtant nécessaire pour vraiment se relier à l'autre dans l'épreuve. Le vrai travail consiste à apprendre qu'une transformation partagée avec quelqu'un d'autre reste possible sans jamais perdre sa propre puissance.",
    9: "Pluton en maison IX transforme la quête de sens en obsession de vérité : une conviction qui ne se contente jamais des réponses de surface, une vraie capacité à remettre en question radicalement une croyance héritée pour en reconstruire une plus vraie. Ce qui grince se joue dans le dogmatisme intense : cette quête peut virer à une conviction si absolue qu'elle ne tolère aucune remise en question, transformer une croyance en outil de pouvoir sur les autres. Ce qui aide à mûrir ici est de saisir qu'une vérité vraiment solide reste ouverte à être questionnée encore.",
    10: "Pluton en maison X marque la carrière d'une puissance transformatrice : une ambition qui vise le pouvoir réel plutôt que la simple reconnaissance, une réussite souvent construite à travers des crises professionnelles qui obligent à tout reconstruire. Ce qui coince se joue dans les rapports de pouvoir professionnels : cette intensité peut créer des conflits marqués avec l'autorité ou la hiérarchie, pousser à un contrôle excessif de sa propre image publique par peur de perdre la maîtrise. Ce que ce placement invite à comprendre est qu'une réussite durable se construit aussi en partageant le pouvoir, pas seulement en le concentrant.",
    11: "Pluton en maison XI transforme les amitiés et les causes collectives en profondeur : des liens amicaux peu nombreux mais d'une intensité rare, un vrai pouvoir de mobilisation autour d'une cause vécue comme vitale. Ce qui coûte le plus se joue dans la méfiance envers le groupe : cette intensité peut nourrir une suspicion sur les motivations réelles des autres membres d'un collectif, ou transformer une cause commune en enjeu de pouvoir personnel. Ce qu'il y a à intégrer est qu'une cause collective reste plus forte quand le pouvoir y est partagé plutôt que concentré.",
    12: "Pluton en maison XII loge la transformation dans l'invisible : des processus intérieurs profonds, souvent vécus en silence, une confrontation avec des peurs archaïques ou un inconscient particulièrement actif, parfois à travers les rêves. Le revers se joue dans le combat solitaire : cette intensité intérieure peut rester totalement cachée, se transformer en angoisse diffuse ou en sabotage silencieux plutôt que d'être affrontée consciemment. Grandir ici, c'est apprendre qu'une transformation vécue seul gagne à être, au moins en partie, reconnue et nommée.",
  },
};
